function LessonArtwork({ lesson }: { lesson: Lesson }) {
  const title = lesson.title.toLowerCase();
  const topic = lesson.topic.toLowerCase();

  // Prefer a real topic-matched photograph or one of the supplied labelled
  // biology references. Every lesson card now receives an image; no microscope
  // placeholder is used as the artwork.
  const image = title.match(/cell|organelle|membrane|cytoplasm|mitosis|cell division/)
    ? { src: title.includes('plant') ? '/resources/plant-cells.jpg' : '/resources/animal-cells.jpg', alt: 'Scientific illustration of cell structure' }
    : title.match(/dna|gene|genetic|heredity|inheritance|chromosome|evolution|biomolecule|molecule/)
      ? { src: '/resources/animal-cells.jpg', alt: 'Living cells containing genetic material and biomolecules' }
      : title.match(/heart|blood|circulation|cardiac/)
        ? { src: '/resources/reference/internal_heart_structure.png', alt: 'Labelled anatomical reference of the human heart' }
        : title.match(/kidney|urinary|nephron|excret/)
          ? { src: '/resources/reference/human_urinary_system.png', alt: 'Labelled human urinary system' }
          : title.match(/brain|neuron|neural|nervous|coordination/)
            ? { src: '/resources/reference/human_brain_anatomy.png', alt: 'Labelled anatomy of the human brain' }
            : title.match(/reproduct|sperm|ovary|fertilis|menstrual/)
              ? { src: title.match(/female|ovary|menstrual/) ? '/resources/reference/female_reproductive_system.png' : '/resources/reference/male_reproductive_system.png', alt: 'Labelled human reproductive system' }
              : title.match(/bone|joint|skeleton|movement|locomotion|muscle/)
                ? { src: '/resources/reference/synovial_joint.png', alt: 'Labelled structure of a synovial joint' }
                : title.match(/immune|antibody|defence|pathogen|disease|infection/)
                  ? { src: '/resources/reference/antibody_structure.png', alt: 'Labelled antibody structure' }
                  : title.match(/worm|parasite|wuchereria/)
                    ? { src: '/resources/reference/wuchereria_bancrofti_morphology_lifecycle.png', alt: 'Wuchereria bancrofti morphology and life cycle' }
                    : title.match(/tooth|digest|digestion/)
                      ? { src: '/resources/digestive-system-reference.png', alt: 'Labelled human digestive system' }
                      : title.match(/breath|lung|gas exchange|respiration/)
                        ? { src: '/resources/frog.jpg', alt: 'Animal life and gas exchange in a living organism' }
                        : title.match(/pollination|pollen/)
                          ? { src: '/resources/honeybee-pollination.jpg', alt: 'Honeybee pollinating a flower' }
                          : title.match(/flower|stamen|carpel|morphology|anatomy of flowering/)
                            ? { src: '/resources/hibiscus-flower.jpg', alt: 'Hibiscus flower showing visible floral structures' }
                            : title.match(/seed|fruit|nutrition|food|diet|vitamin|biomolecule/)
                              ? { src: '/resources/fruits-seeds.jpg', alt: 'Fresh fruits and seeds' }
                              : title.match(/forest|ecosystem|biodiversity|habitat|environment|food chain|conservation|living world|classification|microorganism|microbe|bacteria/)
                                ? { src: '/resources/forest-ecosystem.jpg', alt: 'Forest ecosystem and biodiversity' }
                                : title.match(/frog|animal|animal kingdom|animal life|adaptation|zoology|tissue/)
                                  ? { src: '/resources/frog.jpg', alt: 'Animal life in its natural habitat' }
                                  : title.match(/plant|leaf|photosynthesis|root|stem|botany|transpiration|growth|respiration in plants/)
                                    ? { src: '/resources/leaf-closeup.jpg', alt: 'Close-up photograph of a green leaf' }
                                    : topic.includes('plant')
                                      ? { src: '/resources/hibiscus-flower.jpg', alt: 'Flowering plant' }
                                      : topic.includes('ecology') || topic.includes('biodiversity')
                                        ? { src: '/resources/forest-ecosystem.jpg', alt: 'Forest ecosystem' }
                                        : topic.includes('human') || topic.includes('zoology')
                                          ? { src: '/resources/frog.jpg', alt: 'Animal life' }
                                          : { src: '/resources/animal-cells.jpg', alt: 'Scientific illustration of living cells' };

  return (
    <img
      className="lesson-photo"
      src={image.src}
      alt={image.alt + ' — ' + lesson.title}
      loading="lazy"
    />
  );
}

