const advancedSeeds:AdvancedSeed[] = [
{id:1101,course:'BSc',topic:'Botany',title:'Plant Diversity and Systematics',summary:'Compare major plant groups, their diagnostic characters, life cycles, classification and evolutionary relationships.',paragraphs:['Plant systematics identifies, names and classifies plants using morphology, anatomy, reproduction and molecular evidence. A reliable identification uses several diagnostic characters rather than one superficial resemblance.','Algae are mostly aquatic photosynthetic organisms. Bryophytes lack vascular tissues; pteridophytes have vascular tissues but reproduce by spores; gymnosperms bear naked seeds; angiosperms produce flowers and fruits enclosing seeds.','Plant life cycles alternate between a sporophyte that produces spores by meiosis and a gametophyte that produces gametes. The dominant generation and its dependence differ among plant groups.'],diagram:'Plant groups and alternation of generations',labels:['Algae','Bryophytes','Pteridophytes','Gymnosperms','Angiosperms','Sporophyte'],quiz:{q:'Which plant group produces naked seeds?',options:['Gymnosperms','Bryophytes','Algae','Liverworts'],answer:0,why:'Gymnosperm seeds are not enclosed within an ovary or fruit.'},extra:[{q:'Which group has vascular tissue but reproduces by spores?',options:['Pteridophytes','Bryophytes','Gymnosperms','Angiosperms'],answer:0,why:'Pteridophytes are seedless vascular plants.'},{q:'Which generation is dominant in mosses?',options:['Gametophyte','Sporophyte','Seedling','Embryo only'],answer:0,why:'The moss gametophyte is the conspicuous dominant generation.'},{q:'Which evidence supports modern plant systematics?',options:['DNA sequence comparison','Height alone','Leaf colour alone','Habitat alone'],answer:0,why:'Molecular data complement morphological and anatomical evidence.'}],example:'A fern is a seedless vascular plant; a pine is a gymnosperm; a mango is an angiosperm.',memory:'Bryophytes: non-vascular; pteridophytes: vascular spores; gymnosperms: naked seeds; angiosperms: flowers and fruits.'},
{id:1102,course:'BSc',topic:'Botany',title:'Plant Anatomy, Morphology and Development',summary:'Relate plant organ structure to tissue systems, meristems, primary and secondary growth, and transport.',paragraphs:['Plant morphology studies roots, stems, leaves, flowers, fruits and seeds, including modifications such as rhizomes, tendrils, storage roots and spines. Identify an organ by its origin and structure, not appearance alone.','The dermal tissue system protects the plant, ground tissues support storage and photosynthesis, and vascular tissues transport materials. Xylem conducts water and mineral ions; phloem transports organic solutes.','Apical meristems contribute to primary growth in length. Vascular cambium and cork cambium are lateral meristems involved in secondary growth in girth. Tissue arrangement differs among roots, stems and leaves.'],diagram:'Plant tissue systems and secondary growth',labels:['Epidermis','Cortex','Xylem','Phloem','Cambium','Meristem'],quiz:{q:'Which meristem is mainly responsible for secondary growth in girth?',options:['Vascular cambium','Root cap','Epidermis','Palisade mesophyll'],answer:0,why:'Vascular cambium produces secondary xylem and phloem.'},extra:[{q:'Which tissue conducts water and mineral ions?',options:['Xylem','Phloem','Cork','Collenchyma'],answer:0,why:'Xylem conducts water and dissolved mineral ions.'},{q:'A rhizome is a modified:',options:['Stem','Leaf blade','Root hair','Flower'],answer:0,why:'A rhizome is an underground stem with nodes and buds.'},{q:'Phloem mainly transports:',options:['Organic assimilates','Only oxygen','Mineral crystals only','Pollen'],answer:0,why:'Phloem transports sugars and other organic solutes.'}],example:'A potato tuber is a modified stem because it has nodes, internodes and buds.',memory:'Identify organs by origin, tissue arrangement and function.'},
{id:1103,course:'BSc',topic:'Botany',title:'Plant Physiology and Metabolism',summary:'Study water relations, mineral nutrition, photosynthesis, respiration, translocation and plant growth regulators.',paragraphs:['Water potential, osmosis and transpiration explain water movement through plants. Water generally moves down a water-potential gradient; root uptake and evaporation from leaves contribute to the transpiration stream.','Photosynthesis occurs in chloroplasts. Light-dependent reactions generate ATP and NADPH, while carbon fixation uses these products to build carbohydrates. C3, C4 and CAM pathways differ in initial carbon fixation and water-use strategies.','Respiration transfers energy from organic molecules to ATP. Mineral nutrients have specific structural and metabolic roles. Auxins, gibberellins, cytokinins, abscisic acid and ethylene regulate growth and stress responses.'],diagram:'Photosynthesis, respiration and plant water relations',labels:['Stoma','Xylem','Chloroplast','Thylakoid','Stroma','Phloem'],quiz:{q:'The Calvin cycle occurs in the:',options:['Chloroplast stroma','Thylakoid lumen','Cytosol only','Mitochondrial matrix'],answer:0,why:'Carbon fixation reactions of the Calvin cycle occur in the chloroplast stroma.'},extra:[{q:'Which enzyme initially fixes carbon dioxide in C4 mesophyll cells?',options:['PEP carboxylase','Amylase','Pepsin','ATP synthase'],answer:0,why:'PEP carboxylase catalyses the initial fixation into a four-carbon compound.'},{q:'Which hormone promotes stomatal closure during water stress?',options:['Abscisic acid','Gibberellin','Auxin','Cytokinin'],answer:0,why:'ABA promotes stomatal closure and stress responses.'},{q:'Glycolysis occurs in the:',options:['Cytosol','Thylakoid','Nucleus','Cell wall'],answer:0,why:'Glycolysis takes place in the cytosol.'}],example:'Maize is a C4 plant that initially fixes CO2 into a four-carbon compound.',memory:'Light reactions generate ATP/NADPH; the Calvin cycle fixes carbon; respiration transfers energy to ATP.'},
{id:1104,course:'BSc',topic:'Botany',title:'Plant Genetics, Molecular Biology and Biotechnology',summary:'Connect inheritance, chromosome behaviour, gene expression, plant tissue culture and genetic engineering.',paragraphs:['Mendelian inheritance explains segregation and independent assortment in suitable crosses. Linkage, crossing over, gene interactions and cytoplasmic inheritance explain patterns that do not follow simple ratios.','Molecular biology follows information from DNA to RNA to protein. DNA replication is semi-conservative; transcription produces RNA, and translation at ribosomes assembles amino acids into polypeptides.','Plant tissue culture grows cells or tissues aseptically on defined media. Totipotency is the capacity of a plant cell to regenerate a whole plant under suitable conditions. Genetic transformation requires selection and validation of regenerated lines.'],diagram:'DNA expression and plant tissue culture workflow',labels:['Chromosome','DNA','RNA','Protein','Explant','Regenerated plant'],quiz:{q:'The ability of a plant cell to regenerate a whole plant is called:',options:['Totipotency','Osmosis','Phototropism','Transpiration'],answer:0,why:'Totipotency is the developmental capacity to form a complete plant.'},extra:[{q:'Crossing over occurs during:',options:['Prophase I of meiosis','G1 phase','Cytokinesis','Mitosis metaphase'],answer:0,why:'Homologous chromosomes exchange segments during prophase I.'},{q:'Which enzyme synthesises RNA from a DNA template?',options:['RNA polymerase','Amylase','Pepsin','Lipase'],answer:0,why:'RNA polymerase catalyses transcription.'},{q:'Why is aseptic technique essential in tissue culture?',options:['To prevent microbial contamination','To stop cell division','To remove all hormones','To increase soil erosion'],answer:0,why:'Microbial contaminants can damage or outcompete cultured plant material.'}],example:'A leaf explant may form callus and regenerate shoots and roots on suitable media.',memory:'Inheritance explains transmission; molecular biology explains gene expression; tissue culture depends on asepsis and totipotency.'},
{id:1111,course:'BSc',topic:'Zoology',title:'Animal Diversity, Classification and Evolution',summary:'Compare animal phyla and chordate classes using body organisation, symmetry, germ layers and evolutionary relationships.',paragraphs:['Animal classification uses levels of organisation, symmetry, germ layers, body cavity, segmentation, anatomy, development and molecular evidence. Several characters should be considered together.','Non-chordate groups include sponges, cnidarians, flatworms, roundworms, annelids, arthropods, molluscs and echinoderms. Learn their diagnostic characters and representative examples.','Chordates possess a notochord, dorsal hollow nerve cord, pharyngeal slits and post-anal tail at some developmental stage. Modern phylogeny combines morphology, embryology and molecular data to infer common ancestry.'],diagram:'Animal phyla and chordate character map',labels:['Porifera','Cnidaria','Annelida','Arthropoda','Mollusca','Chordata'],quiz:{q:'Which feature is characteristic of chordates at some developmental stage?',options:['Notochord','Jointed appendages in all species','Water vascular system','Cnidoblasts'],answer:0,why:'The notochord is one of the defining chordate characters.'},extra:[{q:'Which phylum has jointed appendages?',options:['Arthropoda','Porifera','Cnidaria','Platyhelminthes'],answer:0,why:'Jointed appendages are characteristic of arthropods.'},{q:'Which phylum has a water vascular system?',options:['Echinodermata','Annelida','Mollusca','Arthropoda'],answer:0,why:'The water vascular system is characteristic of echinoderms.'},{q:'A true coelom is a body cavity:',options:['Completely lined by mesoderm','Inside the digestive tract','Within a blood cell','Made of cartilage'],answer:0,why:'A true coelom is lined by mesoderm.'}],example:'Arthropods have jointed appendages; echinoderms have a water vascular system; chordates possess a notochord at some stage.',memory:'Compare symmetry, germ layers, coelom, segmentation and chordate characters.'},
{id:1112,course:'BSc',topic:'Zoology',title:'Animal Cell Biology and Development',summary:'Examine animal-cell organisation, cell cycle, gametogenesis, fertilisation and early embryonic development.',paragraphs:['Animal cells contain a plasma membrane, cytoplasm, nucleus and specialised organelles. Membrane trafficking, cytoskeletal movement and cell signalling coordinate cellular activity.','The cell cycle includes interphase and division. Checkpoints monitor DNA integrity and completion of key events. Mitosis distributes chromosomes to daughter cells; meiosis reduces chromosome number and generates variation.','Development begins at fertilisation. Cleavage divisions produce blastomeres, followed by blastulation. Gastrulation establishes primary germ layers, and subsequent patterning and differentiation produce tissues and organs.'],diagram:'Animal cell and early embryonic development',labels:['Nucleus','Mitochondrion','Golgi','ER','Cleavage','Blastula'],quiz:{q:'Which process reduces chromosome number to form haploid gametes?',options:['Meiosis','Mitosis','Budding','Binary fission'],answer:0,why:'Meiosis reduces ploidy through two divisions after one DNA replication.'},extra:[{q:'Which organelle modifies and sorts many proteins?',options:['Golgi apparatus','Centrosome','Nucleolus only','Lysosome only'],answer:0,why:'The Golgi apparatus modifies, sorts and packages proteins and lipids.'},{q:'Which process establishes primary germ layers?',options:['Gastrulation','Fertilisation','Spermiation','Cytokinesis'],answer:0,why:'Gastrulation establishes the primary germ layers.'},{q:'Which sperm structure contains enzymes involved in egg-coat penetration?',options:['Acrosome','Midpiece','Flagellum','Nucleus'],answer:0,why:'The acrosome contains enzymes that assist sperm interaction with egg coverings.'}],example:'In many mammals, cleavage produces a morula and then a blastocyst before implantation.',memory:'Fertilisation → cleavage → blastulation → gastrulation → organogenesis.'},
{id:1113,course:'BSc',topic:'Zoology',title:'Animal Biochemistry and Metabolic Regulation',summary:'Understand biomolecules, enzyme action, metabolic pathways, ATP transfer and regulation of metabolism.',paragraphs:['Proteins perform structural, catalytic, transport and signalling roles; carbohydrates provide energy and structural materials; lipids form membranes and store energy; nucleic acids store and express genetic information.','Enzymes lower activation energy without changing reaction equilibrium. Their activity depends on three-dimensional structure, substrate availability, temperature, pH and regulatory molecules.','Metabolism includes catabolism, which breaks molecules down and captures energy, and anabolism, which builds molecules using energy. ATP couples energy-releasing reactions to energy-requiring cellular work.'],diagram:'Enzyme action and metabolic pathways',labels:['Substrate','Active site','Enzyme','Product','ATP','Pathway'],quiz:{q:'What is the main effect of an enzyme on a reaction?',options:['Lowers activation energy','Changes equilibrium permanently','Is consumed as a reactant','Always raises temperature'],answer:0,why:'Enzymes lower activation energy and are not consumed.'},extra:[{q:'Which bond links amino acids in proteins?',options:['Peptide bond','Glycosidic bond','Phosphodiester bond','Ionic bond only'],answer:0,why:'Peptide bonds link amino acids in polypeptides.'},{q:'ATP is best described as:',options:['A nucleotide energy carrier','A structural polysaccharide','A steroid hormone','A membrane lipid'],answer:0,why:'ATP transfers usable chemical energy in cells.'},{q:'Catabolism generally involves:',options:['Breakdown of molecules','Only protein synthesis','DNA replication only','Cell differentiation only'],answer:0,why:'Catabolic pathways break down molecules and often release energy.'}],example:'A competitive inhibitor competes with substrate for an enzyme active site.',memory:'Enzymes lower activation energy; ATP couples energy transfer; metabolism balances breakdown and synthesis.'},
{id:1114,course:'BSc',topic:'Zoology',title:'Animal Physiology, Homeostasis and Immunology',summary:'Study organ-system function, homeostatic control, innate immunity and adaptive immune responses.',paragraphs:['Animal physiology explains how respiratory, digestive, circulatory, excretory, muscular, nervous and endocrine systems work together to maintain life.','Homeostasis maintains internal variables within workable ranges. A negative-feedback loop detects a deviation and activates effectors that counter the change; neural and endocrine pathways often cooperate.','Innate immunity provides rapid broad defence through barriers, phagocytes and inflammation. Adaptive immunity uses antigen-specific B and T lymphocytes; antibodies, cellular responses and memory contribute to protection.'],diagram:'Homeostatic feedback and immune response',labels:['Stimulus','Receptor','Control centre','Effector','Antigen','Antibody'],quiz:{q:'Which feedback type usually counteracts a deviation from a regulated range?',options:['Negative feedback','Positive feedback in every case','No feedback','Random drift'],answer:0,why:'Negative feedback reduces the initial deviation and stabilises the variable.'},extra:[{q:'Which cells can become antibody-secreting plasma cells?',options:['B lymphocytes','Red blood cells','Platelets','Neurons'],answer:0,why:'Activated B cells can differentiate into plasma cells.'},{q:'The functional unit of the kidney is the:',options:['Nephron','Alveolus','Sarcomere','Neuron'],answer:0,why:'Nephrons filter blood and modify filtrate to form urine.'},{q:'Which muscle protein forms thick filaments?',options:['Myosin','Actin','Elastin','Keratin'],answer:0,why:'Myosin forms thick filaments in skeletal muscle.'}],example:'Insulin promotes glucose uptake and storage when blood glucose rises.',memory:'Homeostasis is dynamic regulation; innate immunity is broad and rapid, adaptive immunity is specific and has memory.'},
{id:1201,course:'NEET',topic:'Botany',title:'NEET Unit 1: Diversity in the Living World — Plant Groups',summary:'Revise plant classification, taxonomic hierarchy, algae, bryophytes, pteridophytes, gymnosperms and angiosperms.',paragraphs:['Taxonomy includes identification, nomenclature and classification. Taxonomic hierarchy arranges organisms in nested categories, while binomial nomenclature gives each species a genus name and specific epithet.','Algae are mostly aquatic photosynthetic organisms. Bryophytes lack vascular tissue; pteridophytes have vascular tissue but reproduce by spores; gymnosperms form naked seeds; angiosperms form flowers and fruits.','Compare plant groups by body organisation, vascular tissue, seeds, reproductive structures and dominant generation. Use the notified syllabus and NCERT descriptions as the boundary for exam revision.'],diagram:'NEET plant group comparison',labels:['Algae','Bryophytes','Pteridophytes','Gymnosperms','Angiosperms','Seeds'],quiz:{q:'Which group has vascular tissue but reproduces by spores?',options:['Pteridophytes','Bryophytes','Gymnosperms','Angiosperms'],answer:0,why:'Pteridophytes are seedless vascular plants.'},extra:[{q:'The basic unit of classification is:',options:['Species','Kingdom','Phylum','Order'],answer:0,why:'Species is the basic unit of taxonomic classification.'},{q:'Which group produces fruits?',options:['Angiosperms','Gymnosperms','Bryophytes','Pteridophytes'],answer:0,why:'Fruits develop from the ovary of angiosperms.'},{q:'The dominant generation in bryophytes is:',options:['Gametophyte','Sporophyte','Seedling','Embryo only'],answer:0,why:'The bryophyte gametophyte is dominant.'}],example:'A fern is a seedless vascular plant; a pine is a gymnosperm; a mango is an angiosperm.',memory:'Bryophytes: non-vascular; pteridophytes: vascular spores; gymnosperms: naked seeds; angiosperms: flowers and fruits.'},
{id:1202,course:'NEET',topic:'Zoology',title:'NEET Unit 1: Diversity in the Living World — Animal Groups',summary:'Revise non-chordate phyla and chordate classes using characters specified in the NMC syllabus.',paragraphs:['Animal groups are compared by level of organisation, symmetry, germ layers, body cavity, segmentation and specialised systems. Use multiple diagnostic characters to identify a phylum.','Non-chordates include sponges, cnidarians, ctenophores, flatworms, roundworms, annelids, arthropods, molluscs, echinoderms and hemichordates. Focus on prescribed characters and examples.','Chordates possess a notochord, dorsal hollow nerve cord, pharyngeal slits and post-anal tail at some developmental stage. Revise chordate classes through their defining adaptations.'],diagram:'Animal phyla and chordate characters',labels:['Porifera','Cnidaria','Annelida','Arthropoda','Mollusca','Chordata'],quiz:{q:'Which is a defining chordate feature at some stage?',options:['Notochord','Jointed appendages','Water vascular system','Cnidoblasts'],answer:0,why:'The notochord is a defining chordate feature.'},extra:[{q:'Which phylum has jointed appendages?',options:['Arthropoda','Porifera','Cnidaria','Platyhelminthes'],answer:0,why:'Arthropods possess jointed appendages.'},{q:'Which phylum has a water vascular system?',options:['Echinodermata','Annelida','Mollusca','Arthropoda'],answer:0,why:'Echinoderms have a water vascular system.'},{q:'Adult echinoderms commonly show:',options:['Pentaradial symmetry','Bilateral symmetry only','Asymmetry only','Spherical symmetry'],answer:0,why:'Many adult echinoderms show pentaradial symmetry.'}],example:'Arthropods have jointed appendages; echinoderms have a water vascular system.',memory:'Use the notified boundary: non-chordates up to phyla and chordates up to classes.'}, {id:1211,course:'NEET',topic:'Botany',title:'NEET Unit 2: Structural Organisation in Plants',summary:'Revise morphology, modifications, tissues, anatomy of roots, stems and leaves, inflorescences, flowers, fruits, seeds and prescribed plant families.',paragraphs:['Plant morphology covers roots, stems, leaves, inflorescences, flowers, fruits and seeds. Learn their parts, arrangements and common modifications, identifying structures by origin and function.','Plant anatomy compares epidermal, ground and vascular tissues in root, stem and leaf sections. Understand xylem and phloem arrangement, vascular bundles, stomata, mesophyll and secondary growth where included.','For family-level questions, revise the diagnostic floral characters, inflorescence, androecium, gynoecium and fruit type of the families explicitly listed in the NMC syllabus and NCERT. Use labelled floral formulae and diagrams to compare them.'],diagram:'Plant organs, vascular tissues and flower structure',labels:['Root','Stem','Leaf','Xylem','Phloem','Flower'],quiz:{q:'Which plant tissue transports prepared food?',options:['Phloem','Xylem','Cork','Collenchyma'],answer:0,why:'Phloem transports sugars and other organic assimilates.'},extra:[{q:'Which tissue conducts water and mineral ions?',options:['Xylem','Phloem','Epidermis only','Cork'],answer:0,why:'Xylem conducts water and dissolved mineral ions.'},{q:'A tendril in pea is a modification of the:',options:['Leaf','Root','Flower','Fruit'],answer:0,why:'In pea, tendrils are modified leaf structures.'},{q:'The ovary develops into the:',options:['Fruit','Seed coat','Pollen grain','Stigma'],answer:0,why:'The ovary usually develops into the fruit.'}],example:'Compare a dicot root and stem by the arrangement of vascular tissues, not just their outer shape.',memory:'Morphology = external form; anatomy = internal structure; xylem conducts water, phloem transports assimilates.'},
{ id:1212,course:'NEET',topic:'Zoology',title:'NEET Unit 2: Structural Organisation in Animals',summary:'Revise animal tissues and the prescribed morphology, anatomy and organ systems of insects and frogs.',paragraphs:['Animal tissues include epithelial, connective, muscular and nervous tissues. Compare their cell arrangement, matrix, location and function; tissue specialisation supports division of labour in organs.','The syllabus includes structural organisation and organ systems in selected animals. For insects such as cockroach, focus on external morphology and the digestive, circulatory, respiratory, excretory, nervous and reproductive systems as prescribed.','For frog, connect external features and internal anatomy with digestion, respiration, circulation, excretion, nervous coordination and reproduction. Learn the labelled structures and the functions stated in NCERT rather than relying on isolated diagrams.'],diagram:'Animal tissue types and organ-system organisation',labels:['Epithelium','Connective','Muscle','Nervous tissue','Trachea','Nephron-like tubule'],quiz:{q:'Which animal tissue is specialised for transmitting impulses?',options:['Nervous tissue','Adipose tissue','Cartilage','Epithelial tissue'],answer:0,why:'Nervous tissue receives and transmits information.'},extra:[{q:'Which tissue commonly lines body surfaces and cavities?',options:['Epithelial tissue','Muscular tissue','Nervous tissue','Bone only'],answer:0,why:'Epithelium covers surfaces and lines cavities and organs.'},{q:'In insects, gas exchange commonly occurs through:',options:['Tracheal system','Alveoli','Gills in every species','Lungs with diaphragm'],answer:0,why:'Insects use a tracheal system of spiracles, tracheae and tracheoles.'},{q:'Which tissue connects muscle to bone?',options:['Tendon','Ligament','Cartilage','Epithelium'],answer:0,why:'Tendons connect muscle to bone; ligaments connect bone to bone.'}],example:'Compare insect tracheal respiration with frog cutaneous and pulmonary respiration.',memory:'Animal tissues: epithelial, connective, muscular and nervous; learn the prescribed insect and frog organ systems.'},
{id:1203,course:'NEET',topic:'Core Biology',title:'NEET Unit 3: Cell Structure, Biomolecules and Cell Division',summary:'Master cell theory, cell organelles, biomolecules, enzymes, mitosis and meiosis.',paragraphs:['Prokaryotic and eukaryotic cells share a plasma membrane, cytoplasm, ribosomes and genetic material, but differ in internal compartmentalisation and nuclear organisation.','Carbohydrates, proteins, lipids and nucleic acids have distinct structures and functions. Enzymes catalyse reactions and their activity depends on structure, substrate and environmental conditions.','The cell cycle includes interphase and division. Mitosis usually produces two genetically similar daughter cells; meiosis reduces chromosome number and creates variation through crossing over and independent assortment.'],diagram:'Cell organelles and cell division',labels:['Nucleus','Mitochondrion','Ribosome','ER','Mitosis','Meiosis'],quiz:{q:'Crossing over normally occurs during:',options:['Prophase I','Mitosis prophase','Telophase II','G1 phase'],answer:0,why:'Homologous chromosomes exchange segments during prophase I.'},extra:[{q:'Which organelle is the main site of protein synthesis?',options:['Ribosome','Lysosome','Vacuole','Golgi body'],answer:0,why:'Ribosomes translate mRNA into polypeptides.'},{q:'A prokaryotic cell lacks a:',options:['Membrane-bound nucleus','Plasma membrane','Ribosome','Cytoplasm'],answer:0,why:'Prokaryotes have a nucleoid, not a membrane-bound nucleus.'},{q:'Meiosis produces cells that are generally:',options:['Haploid','Always diploid','Without DNA','Identical clones'],answer:0,why:'Meiosis reduces chromosome number by half.'}],example:'Meiosis I separates homologous chromosomes; meiosis II separates sister chromatids.',memory:'Mitosis maintains chromosome number; meiosis halves it and reshuffles genetic material.'},
{id:1204,course:'NEET',topic:'Botany',title:'NEET Unit 4: Plant Physiology',summary:'Revise photosynthesis, plant respiration, mineral nutrition, transport and plant growth and development.',paragraphs:['Photosynthesis captures light energy in chloroplasts. Light reactions occur in thylakoid membranes and generate ATP and NADPH; carbon fixation occurs in the stroma.','Respiration transfers energy from organic molecules to ATP. Glycolysis occurs in the cytosol; aerobic pathways include pyruvate oxidation, Krebs cycle and mitochondrial electron transport.','Plant growth involves cell division, elongation and differentiation. Auxin, gibberellin, cytokinin, abscisic acid and ethylene regulate tropisms, dormancy, germination, senescence and stress responses.'],diagram:'Photosynthesis and respiration pathways',labels:['Thylakoid','Stroma','Glycolysis','Krebs cycle','ETS','Hormones'],quiz:{q:'The Calvin cycle occurs in the:',options:['Stroma','Thylakoid lumen','Cytosol only','Mitochondrial matrix'],answer:0,why:'The Calvin cycle takes place in the chloroplast stroma.'},extra:[{q:'Photolysis of water is associated with:',options:['Photosystem II','Photosystem I only','Krebs cycle','Glycolysis'],answer:0,why:'The oxygen-evolving complex of photosystem II splits water.'},{q:'Which hormone is associated with fruit ripening?',options:['Ethylene','Auxin only','Cytokinin only','ABA only'],answer:0,why:'Ethylene promotes fruit ripening.'},{q:'Glycolysis occurs in the:',options:['Cytosol','Mitochondrial matrix','Thylakoid','Nucleus'],answer:0,why:'Glycolysis occurs in the cytosol.'}],example:'C4 plants initially fix carbon dioxide into a four-carbon compound.',memory:'Light reactions make ATP/NADPH; the Calvin cycle fixes carbon; respiration transfers energy to ATP.'},
{id:1205,course:'NEET',topic:'Zoology',title:'NEET Unit 5: Human Physiology',summary:'Revise digestion, breathing, circulation, excretion, locomotion, neural control and endocrine coordination.',paragraphs:['Human physiology connects structure with function. Digestion makes absorbable molecules; respiratory surfaces exchange gases; blood transports materials; kidneys regulate water, ions and wastes.','The four-chambered heart supports pulmonary and systemic circulation. Valves maintain one-way flow; gas exchange occurs across alveoli by diffusion down partial-pressure gradients.','Movement depends on bones, joints and skeletal muscles. Neural pathways coordinate rapid responses, endocrine glands regulate longer-term functions, and nephrons filter blood and form urine.'],diagram:'Human physiology systems overview',labels:['Alimentary canal','Alveolus','Heart','Nephron','Neuron','Endocrine gland'],quiz:{q:'The functional unit of the kidney is the:',options:['Nephron','Neuron','Alveolus','Sarcomere'],answer:0,why:'Nephrons filter blood and modify filtrate to form urine.'},extra:[{q:'Most gas exchange in human lungs occurs in:',options:['Alveoli','Trachea','Larynx','Bronchi only'],answer:0,why:'Alveoli provide a thin, large surface with capillary contact.'},{q:'Which chamber pumps blood into the aorta?',options:['Left ventricle','Right ventricle','Right atrium','Left atrium'],answer:0,why:'The left ventricle pumps blood into systemic circulation.'},{q:'ADH increases:',options:['Water reabsorption','Glucose digestion','Bile secretion','RBC breakdown'],answer:0,why:'ADH increases water permeability in parts of the nephron collecting system.'}],example:'The right ventricle pumps blood to the lungs; the left ventricle pumps blood to the body.',memory:'For each system learn its organs, process, control and direction of material flow.'},
{id:1206,course:'NEET',topic:'Botany',title:'NEET Unit 6: Sexual Reproduction in Flowering Plants',summary:'Revise flower structure, gametophyte development, pollination, double fertilisation, seeds and fruits.',paragraphs:['A typical flower contains sepals, petals, stamens and carpels. Anthers form pollen grains, while ovules contain the embryo sac. Understand male and female gametophyte development.','Pollination transfers pollen to the stigma. Compatible pollen germinates and a pollen tube grows towards an ovule, delivering two male gametes to the embryo sac.','In double fertilisation, one male gamete fuses with the egg to form a zygote; the other fuses with the central cell nuclei to initiate endosperm formation. The ovule develops into a seed and the ovary commonly develops into a fruit.'],diagram:'Flower reproduction and double fertilisation',labels:['Anther','Stigma','Pollen tube','Ovule','Egg cell','Endosperm'],quiz:{q:'Double fertilisation is characteristic of:',options:['Angiosperms','Bryophytes','Pteridophytes','Gymnosperms'],answer:0,why:'Double fertilisation is characteristic of flowering plants.'},extra:[{q:'Pollen grains are produced in the:',options:['Anther','Stigma','Style','Ovary wall'],answer:0,why:'Pollen develops within anther microsporangia.'},{q:'The ovule develops into the:',options:['Seed','Fruit wall','Petal','Stigma'],answer:0,why:'The ovule develops into a seed after fertilisation.'},{q:'The ovary usually develops into the:',options:['Fruit','Embryo sac','Pollen grain','Anther'],answer:0,why:'The ovary commonly develops into the fruit.'}],example:'In a typical angiosperm embryo sac, the two male gametes take part in two distinct fusions.',memory:'Pollination is pollen transfer; fertilisation is gamete fusion; double fertilisation is characteristic of angiosperms.'},
{id:1207,course:'NEET',topic:'Zoology',title:'NEET Unit 6: Human Reproduction and Reproductive Health',summary:'Revise reproductive anatomy, gametogenesis, menstrual cycle, fertilisation, pregnancy, contraception and reproductive health.',paragraphs:['The male reproductive system produces sperm in seminiferous tubules; the female reproductive system produces oocytes and supports development. Learn the location and function of gonads, ducts and accessory glands.','Gametogenesis produces haploid gametes. The menstrual cycle includes ovarian and uterine changes regulated by FSH, LH, oestrogen and progesterone. Fertilisation commonly occurs in the ampullary region of the oviduct; early cleavage leads to a blastocyst.','Reproductive health includes contraception, prevention of sexually transmitted infections, infertility and assisted reproductive technologies. Learn the science without stigma and distinguish prevention from treatment.'],diagram:'Human reproductive systems and fertilisation pathway',labels:['Testis','Ovary','Oviduct','Uterus','Sperm','Blastocyst'],quiz:{q:'Human fertilisation usually occurs in the:',options:['Ampullary region of the oviduct','Uterine cavity','Vagina','Cervix'],answer:0,why:'Fertilisation most commonly occurs in the ampullary region of the oviduct.'},extra:[{q:'Sperm are produced in the:',options:['Seminiferous tubules','Prostate gland','Vas deferens','Seminal vesicle'],answer:0,why:'Spermatogenesis occurs in seminiferous tubules.'},{q:'Which hormone surge triggers ovulation?',options:['LH','Insulin','Thyroxine','ADH'],answer:0,why:'A mid-cycle LH surge triggers ovulation.'},{q:'Implantation normally occurs in the:',options:['Endometrium','Ovary cortex','Vagina','Cervix canal'],answer:0,why:'The blastocyst implants in the uterine endometrium.'}],example:'Ovulation follows the LH surge; fertilisation commonly occurs in the oviduct.',memory:'Gametogenesis → ovulation → fertilisation → cleavage → implantation.'},
{id:1208,course:'NEET',topic:'Core Biology',title:'NEET Unit 7: Genetics, Molecular Basis and Evolution',summary:'Practise Mendelian inheritance, molecular genetics, gene expression, genetic disorders and evolution.',paragraphs:['Mendelian principles explain segregation and independent assortment in appropriate crosses. Extend this to linkage, sex determination, genetic disorders and variation as specified in the syllabus.','Molecular inheritance involves DNA structure, replication, transcription and translation. Understand the genetic code, gene expression and the major experiments described in NCERT.','Mutation and recombination generate variation; natural selection, genetic drift and gene flow change allele frequencies. Evidence includes fossils, comparative anatomy, biogeography and molecular similarities.'],diagram:'Inheritance, DNA expression and population change',labels:['Allele','Chromosome','DNA','mRNA','Protein','Population'],quiz:{q:'The law of segregation states that:',options:['Alleles separate during gamete formation','Genes blend permanently','All traits are linked','Only dominant alleles enter gametes'],answer:0,why:'The two alleles of a gene segregate during gamete formation.'},extra:[{q:'DNA replication is described as:',options:['Semi-conservative','Conservative only','Dispersive in all cells','Protein-directed only'],answer:0,why:'Each daughter DNA molecule contains one parental and one new strand.'},{q:'Which enzyme joins Okazaki fragments?',options:['DNA ligase','Amylase','Pepsin','Lipase'],answer:0,why:'DNA ligase seals nicks between adjacent DNA fragments.'},{q:'Genetic drift has the strongest random effect in:',options:['Small populations','Infinite populations','Only plants','Populations with no alleles'],answer:0,why:'Sampling effects are strongest in small populations.'}],example:'A heterozygous monohybrid cross under complete dominance gives an expected 3:1 phenotypic ratio.',memory:'Segregation separates alleles; DNA stores information; evolution changes populations over generations.'},
{id:1209,course:'NEET',topic:'Core Biology',title:'NEET Unit 8–9: Human Welfare, Microbes and Biotechnology',summary:'Revise human disease, immunity, useful microbes, recombinant DNA technology and biotechnology applications.',paragraphs:['Human welfare biology includes health and disease, pathogens, immune responses and prevention. Distinguish infectious and non-infectious conditions, and remember that antibiotics do not treat viral infections.','Microorganisms are used in food production, industrial fermentation, antibiotics, sewage treatment, biogas generation and biological control. Their roles depend on species and conditions.','Recombinant DNA technology involves isolating DNA, cutting and joining fragments, introducing a construct into a host, selecting successful cells and validating the product. Applications include medicine and agriculture, alongside biosafety and ethical considerations.'],diagram:'Microbial applications and recombinant DNA workflow',labels:['Microbe','Fermentation','Restriction enzyme','Vector','Host cell','Product'],quiz:{q:'Which enzyme cuts DNA at specific recognition sequences?',options:['Restriction endonuclease','Amylase','Pepsin','Lipase'],answer:0,why:'Restriction endonucleases recognise specific DNA sequences and cleave DNA.'},extra:[{q:'Which microbes commonly help in curd formation?',options:['Lactic acid bacteria','Plasmodium','Tapeworms','Viruses only'],answer:0,why:'Lactic acid bacteria ferment lactose.'},{q:'A vector in genetic engineering is used to:',options:['Carry DNA into a host cell','Digest all proteins','Generate sunlight','Remove all mutations'],answer:0,why:'Vectors carry desired DNA into host cells.'},{q:'Which process helps treat sewage biologically?',options:['Microbial degradation of organic matter','Adding heavy metals','Removing all microbes','Burning wastewater'],answer:0,why:'Microorganisms break down organic matter during sewage treatment.'}],example:'A plasmid vector can carry a selected gene into a bacterial host for cloning or expression.',memory:'Biotechnology workflow: construct → host → selection → expression → validation.'},
{id:1210,course:'NEET',topic:'Core Biology',title:'NEET Unit 10: Ecology, Ecosystems and Biodiversity',summary:'Revise population interactions, ecosystem structure, energy flow, ecological pyramids and biodiversity conservation.',paragraphs:['Ecology studies relationships among organisms and environments. Population attributes include density, natality, mortality, age structure and growth. Interactions include competition, predation, parasitism, mutualism and commensalism.','Ecosystems contain biotic and abiotic components. Producers capture energy, consumers transfer it through food chains and webs, and decomposers return nutrients. Energy transfer is inefficient between trophic levels.','Biodiversity occurs at genetic, species and ecosystem levels. Habitat loss, overexploitation, invasive species, pollution and climate change contribute to decline. Conservation includes in-situ protection and ex-situ measures.'],diagram:'Food web, ecological pyramids and biodiversity',labels:['Producer','Primary consumer','Secondary consumer','Decomposer','Energy flow','Biodiversity'],quiz:{q:'Which ecological pyramid is always upright?',options:['Energy pyramid','Biomass pyramid in every ecosystem','Numbers pyramid in every ecosystem','None'],answer:0,why:'Energy decreases at successive trophic levels, so the energy pyramid is always upright.'},extra:[{q:'The interaction in which both species benefit is:',options:['Mutualism','Parasitism','Competition','Amensalism'],answer:0,why:'Mutualism benefits both interacting species.'},{q:'Which process returns nutrients from dead organic matter?',options:['Decomposition','Predation only','Pollination','Photosynthesis only'],answer:0,why:'Decomposers break down organic matter and release nutrients.'},{q:'Which is an in-situ conservation method?',options:['National park','Seed bank','Botanical garden','Cryopreservation'],answer:0,why:'National parks protect species in natural habitats.'}],example:'Food webs connect multiple food chains and represent complex energy pathways.',memory:'Energy flows one way; nutrients cycle; biodiversity has genetic, species and ecosystem levels.'}
];
const advancedLessons:Lesson[]=advancedSeeds.map(s=>({id:s.id,title:s.title,topic:s.topic,levels:[s.course],difficulty:s.course==='NEET'?'NEET UG 2026 · Biology syllabus':'B.Sc. · common university-level reference',time:'25–35 min',summary:s.summary,concepts:s.paragraphs,diagram:s.diagram,drawSteps:['Read the syllabus-linked concept outline.','Sketch the main structures or process in a logical order.','Add arrows only where transport or a process is involved.','Label structures using the exact biological terms.'],labels:s.labels,quiz:s.quiz,questions:[s.quiz,...s.extra]}));
const advancedExplanations=Object.fromEntries(advancedSeeds.map(s=>[s.id,{heading:s.title+' — concept lesson',paragraphs:s.paragraphs,sections:[{title:'Core concepts',paragraphs:s.paragraphs.slice(0,2)},{title:'Apply and connect',paragraphs:[s.paragraphs[2]]}],example:s.example,memory:s.memory}]));

const allLessons: Lesson[] = [...lessons,...firstYearLessons,...class12Lessons,...advancedLessons];
const class12Explanations = Object.fromEntries(class12ChapterData.map(c=>[c.id,{heading:c.heading,paragraphs:c.paragraphs,example:c.example,memory:c.memory}]));
const class12StoryScenes: Record<number, { title: string; story: string }> = {
  101: { title: 'Bun-Bun visits the flower’s hidden nursery', story: '“Look at this flower,” Bun-Bun whispers, lifting a petal after a morning shower. “A tiny grain of pollen has landed on the sticky stigma. But pollen is only the beginning. How does it reach the ovule hidden deep inside the ovary? And why does a flowering plant need two fusions to begin a seed?” Bun-Bun follows the pollen tube down the style and discovers the two male gametes travelling towards the embryo sac.' },
  102: { title: 'Bun-Bun solves the mystery of a family trait', story: 'At a family garden, Bun-Bun notices that some pea plants are tall while others are short. “Did the plants choose their height?” Bun-Bun asks. A gardener shows two parent plants and their offspring. Together they follow tiny alleles through pollen and egg cells, make a Punnett square, and discover why a hidden recessive trait can reappear in the next generation.' },
  103: { title: 'Bun-Bun enters the cell’s instruction library', story: 'Bun-Bun finds a library whose most precious book is written in four chemical letters: A, T, G and C. A copy machine is opening the double helix, while another room is reading a gene to make RNA. At the far end, ribosomes are joining amino acids into a protein. “The order of the letters matters,” Bun-Bun says. “Let’s follow one instruction from DNA to a working protein.”' },
  104: { title: 'Bun-Bun watches a population change', story: 'A group of beetles lives on a patch of green leaves. Some are easier for birds to spot; others blend into the background. After many generations, Bun-Bun notices that the population looks different. “The beetles did not change because they wanted to,” Bun-Bun explains. “Let’s find out how inherited variation, survival, reproduction, chance and migration can change a population.”' },
  105: { title: 'Bun-Bun guards the body’s busy city', story: 'One morning, a tiny pathogen tries to enter the body city. Skin forms the first wall, mucus catches some invaders, and immune cells rush to the scene. Bun-Bun watches a phagocyte engulf a microbe and later sees lymphocytes recognise a particular antigen. “Why does the body respond faster the next time?” Bun-Bun wonders, discovering immune memory and vaccination.' },
  106: { title: 'Bun-Bun visits the invisible helpers', story: 'Bun-Bun opens a kitchen jar of curd and notices that milk has changed into something tangy and thick. In a nearby bakery, yeast makes dough rise; at a treatment plant, microbes help clean wastewater. “These tiny organisms are doing very different jobs,” Bun-Bun says. “Let’s meet the useful microbes behind food, medicines, sewage treatment, biogas and healthy soil.”' },
  107: { title: 'Bun-Bun follows a gene into a new home', story: 'A scientist has a useful gene but needs a way to copy it and help a host cell read it. Bun-Bun watches a plasmid being opened, a DNA fragment joined with ligase, and a bacterial cell receiving the recombinant plasmid. The successful cells are selected and grown in a carefully controlled vessel. “A tiny DNA change needs a whole carefully checked process,” Bun-Bun says.' },
  108: { title: 'Bun-Bun meets biotechnology outside the laboratory', story: 'At a clinic, Bun-Bun sees a vial of recombinant insulin. In a field, a farmer checks an insect-resistant crop. In a diagnostic lab, a technician looks for a DNA sequence. “Biotechnology is not just one machine or one medicine,” Bun-Bun says. “Let’s see how it helps people—and why safety checks, evidence and responsible use matter.”' },
  109: { title: 'Bun-Bun studies life in a changing habitat', story: 'A pond becomes crowded during the rainy season, then water levels fall in summer. Bun-Bun watches fish, insects and plants respond to temperature, water and food. “A population is more than a head count,” Bun-Bun says, recording births, deaths, immigration, emigration and age groups. The notebook fills with J-shaped and S-shaped growth curves and examples of species interactions.' },
  110: { title: 'Bun-Bun follows energy through a forest', story: 'Sunlight reaches the forest canopy. Leaves capture some of that energy, a caterpillar eats a leaf, and a bird eats the caterpillar. When leaves fall, fungi and bacteria begin breaking them down. “Energy keeps moving and some escapes as heat, but nutrients can return to the soil,” Bun-Bun explains. Together they trace food webs, productivity, decomposition and nutrient cycles.' },
  111: { title: 'Bun-Bun protects a living treasure chest', story: 'Bun-Bun visits a forest where every tree, insect, bird and fungus is part of a living network. A road divides the habitat, and an invasive plant begins spreading. “If one species disappears, what else may be affected?” Bun-Bun asks. The investigation leads to genetic, species and ecosystem diversity, the causes of biodiversity loss, and ways to protect life in its natural home and beyond.' },
  112: { title: 'Bun-Bun follows the scent of chicken pizza', story: '“Mmm… chicken pizza!” Bun-Bun stops outside a bakery. Before taking a bite, the warm smell makes saliva collect in Bun-Bun’s mouth. “But food has not even touched my tongue yet. How did my salivary glands know?” Inside, Bun-Bun follows the first bite from teeth and tongue through the food pipe to the stomach and intestines, meeting enzymes that break food down and tiny villi that absorb nutrients.' },
  113: { title: 'Bun-Bun takes a breath with the lungs', story: 'After running up a hill, Bun-Bun pauses, breathing faster. “Why does my chest expand when I breathe in? Where does the oxygen actually enter my blood?” Bun-Bun watches the diaphragm move down, the lungs expand, and air travel through branching airways to tiny alveoli. There, oxygen crosses into capillaries while carbon dioxide moves the other way.' },
  114: { title: 'Bun-Bun rides through the heart’s four rooms', story: 'Bun-Bun is carrying a parcel of oxygen-poor blood returning from the body. The journey enters the right atrium, passes through a valve into the right ventricle, and heads to the lungs. After picking up oxygen, the blood returns to the left atrium, moves into the powerful left ventricle and is sent through the aorta to the whole body. “Four rooms, one direction, two circuits,” Bun-Bun says. “Let’s draw the real heart so we never mix up its sides.”' },
  115: { title: 'Bun-Bun visits the kidney’s cleaning station', story: 'On a hot afternoon, Bun-Bun notices that very little urine is being made. “The body must be saving water,” Bun-Bun says. Inside a kidney, blood reaches a tiny glomerulus where filtration begins. The tubule takes back useful water and solutes, adds selected wastes, and adjusts the final urine. Bun-Bun follows the nephron and discovers how hormones help the body conserve water.' },
  116: { title: 'Bun-Bun helps the body move', story: 'Bun-Bun bends an elbow to pick up a heavy book. The biceps tightens while the triceps relaxes. “Muscles pull, but they do not push bones,” Bun-Bun notices. A closer look reveals tendons, ligaments, a lubricated joint and microscopic actin and myosin filaments sliding past one another. The movement begins to make sense from the whole skeleton down to the sarcomere.' },
  117: { title: 'Bun-Bun follows a message along a neuron', story: 'A hand touches a hot cup and pulls away quickly. Bun-Bun wonders how a message travelled from the skin to the spinal cord and back to a muscle. The journey follows a sensory neuron, a relay inside the central nervous system and a motor neuron. At a synapse, calcium helps release neurotransmitter. Bun-Bun traces the electrical signal and the chemical hand-off.' },
  118: { title: 'Bun-Bun investigates the body’s message network', story: 'After a meal, blood glucose rises. Bun-Bun watches the pancreas release insulin, and body cells respond by taking up and storing more glucose. Later, when glucose falls, other signals help restore balance. “These messages travel through the blood and act only on cells with the right receptors,” Bun-Bun explains, following the hypothalamus, pituitary and other endocrine glands.' },
  119: { title: 'Bun-Bun meets the body’s defence team', story: 'A splinter breaks the skin and microbes enter. Bun-Bun watches inflammation bring immune cells to the area. An antigen-presenting cell displays a fragment to a T cell; helper T cells coordinate the response, while B cells can become antibody-making plasma cells. Some cells remain as memory cells. “The next response can be quicker because the body remembers,” Bun-Bun says.' },
  120: { title: 'Bun-Bun follows the beginning of a new life', story: 'Bun-Bun looks at a diagram of the reproductive system and asks how two specialised cells can begin development. The journey follows sperm formation in the testes and oocyte development in the ovary. After ovulation, fertilisation usually occurs in the ampullary region of the oviduct. The early embryo divides as it travels to the uterus, where a blastocyst may implant.' },
  121: { title: 'Bun-Bun learns how informed choices protect health', story: 'A group of students brings thoughtful questions to a health educator. They discuss consent, reliable information, contraception, prevention of sexually transmitted infections, testing and when to seek medical care. Bun-Bun reminds everyone that reproductive health is about dignity, safety and informed choices—not embarrassment or pressure.' },
  122: { title: 'Bun-Bun sorts out a genetic puzzle', story: 'Bun-Bun examines two homologous chromosomes and notices that they carry the same genes but may have different alleles. During meiosis, crossing over and independent assortment create new combinations. After fertilisation, the alleles from two parents meet in a zygote. “Let’s use chromosomes, family patterns and DNA evidence to understand inheritance,” Bun-Bun says.' },
  123: { title: 'Bun-Bun explores the story of life through time', story: 'At a museum, Bun-Bun sees fossils, animal skeletons and DNA comparisons. Some clues reveal shared ancestry; others show how populations became different after barriers reduced gene flow. “Evolution is not a ladder with a final goal,” Bun-Bun says. “It is the changing history of populations, shaped by variation, selection, chance and isolation.”' },
  124: { title: 'Bun-Bun takes biology into the real world', story: 'A farmer is facing crop pests, a clinic needs a reliable diagnostic test, and a wildlife team is protecting a threatened species. Bun-Bun helps each team ask the same questions: What is the evidence? Which biological principle can help? Is the solution safe, fair and practical? Applied biology turns scientific understanding into decisions that must be tested and improved.' }
};
const class12Stories = Object.fromEntries(class12ChapterData.map(c=>[c.id,class12StoryScenes[c.id]]));
