function StepDrawingDiagram({lesson,step}:{lesson:Lesson;step:number}) {
 const labels = lesson.labels.slice(0,8);
 const visible = Math.max(1,Math.min(labels.length,Math.ceil(((step+1)/Math.max(lesson.drawSteps.length,1))*labels.length)));
 const palette = ['#d9ebd0','#f8dfb8','#dce8f4','#f3d8e5','#e6e0f5','#d7eee9','#f6e8c8','#dce6d2'];
 const gap = 14, cardW = Math.min(118,(560-48-gap*(labels.length-1))/labels.length);
 const startX = (560-(cardW*labels.length+gap*(labels.length-1)))/2;
 return <div className="step-drawing-canvas" role="img" aria-label={lesson.diagram+' being drawn step by step'}>
  <div className="step-canvas-title">{lesson.diagram}</div>
  <svg viewBox="0 0 560 230" className="step-drawing-svg">
   <defs><marker id="diagram-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="none" stroke="#66866b" strokeWidth="1.2"/></marker></defs>
   {labels.map((label,i)=>i<visible?<g key={label} className="drawn-node" style={{animationDelay:(i*.08)+'s'}}>
    {i>0&&<path d={'M '+(startX+(i-1)*(cardW+gap)+cardW)+' 111 L '+(startX+i*(cardW+gap)-4)+' 111'} stroke="#66866b" strokeWidth="3" markerEnd="url(#diagram-arrow)" fill="none"/>}
    <rect x={startX+i*(cardW+gap)} y="55" width={cardW} height="112" rx="18" fill={palette[i%palette.length]} stroke="#719176" strokeWidth="2"/>
    <circle cx={startX+i*(cardW+gap)+cardW/2} cy="85" r="17" fill="#fffdf8" stroke="#719176" strokeWidth="2"/>
    <path d={i%3===0?'M '+(startX+i*(cardW+gap)+cardW/2-9)+' 85 q9 -15 18 0 q-9 15 -18 0':i%3===1?'M '+(startX+i*(cardW+gap)+cardW/2-10)+' 85 h20 m-10 -10 v20':'M '+(startX+i*(cardW+gap)+cardW/2-9)+' 78 l18 14 m-18 0 l18 -14'} fill="none" stroke="#547d5a" strokeWidth="2.5" strokeLinecap="round"/>
    <text x={startX+i*(cardW+gap)+cardW/2} y="128" textAnchor="middle" fontSize="10" fontWeight="700" fill="#355b40">{label.length>18?label.slice(0,17)+'…':label}</text>
    <text x={startX+i*(cardW+gap)+cardW/2} y="147" textAnchor="middle" fontSize="9" fill="#718076">Part {i+1}</text>
   </g>:null)}
   {visible<labels.length&&<text x="280" y="205" textAnchor="middle" fontSize="11" fill="#718076">Next: add {labels[visible]}</text>}
   {visible===labels.length&&<text x="280" y="205" textAnchor="middle" fontSize="12" fontWeight="700" fill="#47734a">Diagram structure complete</text>}
  </svg>
  <div className="canvas-stage-caption">Stage {step+1} of {lesson.drawSteps.length} · {visible} of {labels.length} parts drawn</div>
 </div>;
}

