      {s(2) && <g fill="#e5bd65" stroke="#98713a" strokeWidth="2"><ellipse cx="225" cy="105" rx="13" ry="9"/><ellipse cx="395" cy="105" rx="13" ry="9"/><ellipse cx="250" cy="135" rx="11" ry="8"/><ellipse cx="370" cy="135" rx="11" ry="8"/></g>}
